package io.knowledgebrain.gateway;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;
class DiscussionProxyTest {
 @Test void creatorAndReplyKeysAndObservedDiscussionVersionAreForwarded()throws Exception{var f=new GroupProxyTest();f.init();String root="/api/groups/"+f.id+"/studies/"+f.id+"/discussions";for(String path:List.of(root,root+"/"+f.id+"/replies")){var r=f.request("POST",path);r.addHeader("Idempotency-Key","a".repeat(32));r.addHeader("If-Match","\"di1\"");r.addHeader("X-Principal-Id",f.id);r.addHeader("Authorization","Bearer spoof");r.setContent("{}".getBytes());f.proxy.proxy(r);verify(f.transport).send(eq(new GatewayRoute("collaboration",path)),eq("POST"),argThat(h->h.get("Idempotency-Key").equals(List.of("a".repeat(32)))&&h.get("If-Match").equals(List.of("\"di1\""))&&!h.containsKey("Authorization")&&!h.containsKey("X-Principal-Id")),any());}}
 @Test void replyPagesRejectOversizedCountsAndWritesRequireOneKey(){var f=new GroupProxyTest();assertDoesNotThrow(f::init);String root="/api/groups/"+f.id+"/studies/"+f.id+"/discussions/"+f.id+"/replies";for(String q:List.of("limit=11","limit=1&limit=2","authorId="+f.id,"before=2")){var r=f.request("GET",root);r.setQueryString(q);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(r));}var missing=f.request("POST",root);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(missing));verifyNoInteractions(f.transport);}
}
